insert into public.categories (name, slug, parent_id, attention_level, sophos_firewall_category, description)
select v.name, v.slug, p.id, v.attention::public.attention_level, v.firewall, v.description
from (values
  ('Remote desktop and support', 'remote-access/remote-desktop-and-support', 'remote-access', 'review', 'Remote access', 'Tools that let someone see and control this computer or another one over the network, attended or unattended. Examples: AnyDesk, TeamViewer, RustDesk, Chrome Remote Desktop, Splashtop, Parsec.'),
  ('Remote management agents (RMM)', 'remote-access/remote-management-agents-rmm', 'remote-access', 'review', 'Remote access', 'Agents of IT management platforms that run scripts, install software and open remote sessions. Examples: NinjaOne, Datto RMM, Atera, ConnectWise Automate.'),
  ('VNC and RDP servers', 'remote-access/vnc-and-rdp-servers', 'remote-access', 'review', 'Remote access', 'Software that accepts incoming remote desktop connections on this computer. Examples: RealVNC Server, TightVNC, UltraVNC, RDP Wrapper.'),
  ('SSH and terminal clients', 'remote-access/ssh-and-terminal-clients', 'remote-access', 'info', 'Remote access', 'Clients used to open shells on other systems. Examples: PuTTY, MobaXterm, Termius, Windows Terminal.'),
  ('Corporate VPN clients', 'proxy-and-tunnel/corporate-vpn-clients', 'proxy-and-tunnel', 'info', 'Proxy and tunnel', 'VPN clients usually deployed by the organization to reach internal networks. Examples: FortiClient VPN, Cisco Secure Client, GlobalProtect, OpenVPN Connect.'),
  ('Consumer VPN and proxy services', 'proxy-and-tunnel/consumer-vpn-and-proxy-services', 'proxy-and-tunnel', 'review', 'Proxy and tunnel', 'Personal VPN or proxy apps and browser extensions that route traffic through a third-party service. Examples: Urban VPN Proxy, Hola VPN, Hotspot Shield, NordVPN, Proton VPN.'),
  ('Tunnels and mesh networks', 'proxy-and-tunnel/tunnels-and-mesh-networks', 'proxy-and-tunnel', 'review', 'Proxy and tunnel', 'Tools that expose local services to the internet or join the computer to an overlay network. Examples: ngrok, cloudflared, Tailscale, ZeroTier, frp.'),
  ('Anonymizers', 'proxy-and-tunnel/anonymizers', 'proxy-and-tunnel', 'not_allowed', 'Proxy and tunnel', 'Software built to hide the user''s identity or bypass network controls. Examples: Tor Browser, Psiphon, Ultrasurf.'),
  ('FTP and SFTP clients', 'file-transfer/ftp-and-sftp-clients', 'file-transfer', 'info', 'File transfer', 'Clients for moving files to and from servers. Examples: FileZilla, WinSCP, Cyberduck.'),
  ('Direct file sharing', 'file-transfer/direct-file-sharing', 'file-transfer', 'review', 'File transfer', 'Apps that send files between devices or people outside managed storage. Examples: LocalSend, Send Anywhere, WeTransfer.'),
  ('Cloud storage sync', 'storage-and-backup/cloud-storage-sync', 'storage-and-backup', 'info', 'Storage and backup', 'Desktop clients and extensions that sync files with a cloud drive. Examples: OneDrive, Google Drive, Dropbox, Box, Application Launcher For Drive.'),
  ('Backup software', 'storage-and-backup/backup-software', 'storage-and-backup', 'info', 'Storage and backup', 'Software that copies data to local or remote backup targets. Examples: Veeam Agent, Acronis Cyber Protect, Backblaze, Macrium Reflect.'),
  ('Torrent clients', 'p2p/torrent-clients', 'p2p', 'not_allowed', 'P2P', 'BitTorrent clients and torrent search tools. Examples: qBittorrent, µTorrent, BitTorrent, Transmission.'),
  ('Other P2P networks', 'p2p/other-p2p-networks', 'p2p', 'not_allowed', 'P2P', 'File sharing over other peer-to-peer networks. Examples: eMule, Soulseek, Shareaza.'),
  ('Download managers', 'download-applications/download-managers', 'download-applications', 'review', 'Download applications', 'Tools that accelerate or schedule downloads outside the browser. Examples: Internet Download Manager, JDownloader, Free Download Manager.'),
  ('Media downloaders', 'download-applications/media-downloaders', 'download-applications', 'review', 'Download applications', 'Tools that save video or audio from streaming sites. Examples: yt-dlp, 4K Video Downloader, Video DownloadHelper.'),
  ('Video meetings', 'conferencing/video-meetings', 'conferencing', 'info', 'Conferencing', 'Meeting and webinar clients and their browser extensions. Examples: Zoom Workplace, Microsoft Teams, Cisco Webex, Cisco Webex Extension.'),
  ('Team chat', 'instant-messenger/team-chat', 'instant-messenger', 'info', 'Instant messenger', 'Workplace messaging platforms. Examples: Slack, Mattermost, Rocket.Chat.'),
  ('Consumer messaging', 'instant-messenger/consumer-messaging', 'instant-messenger', 'review', 'Instant messenger', 'Personal messaging apps on a work computer. Examples: WhatsApp, Telegram, Signal, Discord.'),
  ('Softphones', 'voip/softphones', 'voip', 'info', 'VoIP', 'Telephony clients that place or receive calls over IP. Examples: 3CX, Zoiper, MicroSIP.'),
  ('Mail clients', 'desktop-mail/mail-clients', 'desktop-mail', 'info', 'Desktop mail', 'Desktop email clients and their add-ins. Examples: Outlook, Thunderbird, eM Client, Mailbird.'),
  ('Web mail helpers', 'web-mail/web-mail-helpers', 'web-mail', 'info', 'Web mail', 'Browser extensions that add features to web mail. Examples: Boomerang for Gmail, Mailtrack.'),
  ('Video streaming', 'streaming-media/video-streaming', 'streaming-media', 'info', 'Streaming media', 'Players and extensions for video streaming services, including DRM components. Examples: Netflix, Player do NOW NET Claro, Disney+.'),
  ('Music and podcasts', 'streaming-media/music-and-podcasts', 'streaming-media', 'info', 'Streaming media', 'Music and podcast streaming clients. Examples: Spotify, Deezer, Apple Music.'),
  ('Media players and casting', 'streaming-media/media-players-and-casting', 'streaming-media', 'info', 'Streaming media', 'Local media players and casting receivers. Examples: VLC, PotPlayer, AllCast Receiver.'),
  ('Social network apps and extensions', 'social-networking/social-network-apps-and-extensions', 'social-networking', 'info', 'Social networking', 'Apps and extensions for social networks. Examples: Facebook, Instagram, LinkedIn, X.'),
  ('Game launchers and stores', 'gaming/game-launchers-and-stores', 'gaming', 'review', 'Gaming', 'Platforms that install and run games. Examples: Steam, Epic Games Launcher, Battle.net, EA app.'),
  ('Games', 'gaming/games', 'gaming', 'review', 'Gaming', 'Installed games and browser games. Examples: Minecraft, Roblox, League of Legends.'),
  ('Shopping assistants', 'e-commerce/shopping-assistants', 'e-commerce', 'review', 'E-commerce', 'Coupon, cashback, price tracking and wish list extensions; many read every page the user visits. Examples: Add to Amazon Wish List, Honey, Keepa.'),
  ('AI assistants', 'generative-ai/ai-assistants', 'generative-ai', 'review', 'Generative AI', 'Chat assistants as desktop apps or browser extensions. Examples: ChatGPT, Claude, Microsoft Copilot, Gemini.'),
  ('AI browser extensions', 'generative-ai/ai-browser-extensions', 'generative-ai', 'review', 'Generative AI', 'Sidebars, writers and summarizers that read the content of the pages the user visits. Examples: Monica, Merlin, Sider.'),
  ('AI coding assistants', 'generative-ai/ai-coding-assistants', 'generative-ai', 'review', 'Generative AI', 'Code completion and coding agents inside IDEs and terminals. Examples: GitHub Copilot, Cursor, Codeium.'),
  ('Local AI runtimes', 'generative-ai/local-ai-runtimes', 'generative-ai', 'review', 'Generative AI', 'Tools that download and run models on the computer. Examples: Ollama, LM Studio, GPT4All.'),
  ('Office and documents', 'general-business/office-and-documents', 'general-business', 'info', 'General business', 'Office suites, PDF tools and document viewers. Examples: Microsoft 365 Apps, Adobe Acrobat, LibreOffice, Google Docs Offline.'),
  ('Notes and knowledge', 'general-business/notes-and-knowledge', 'general-business', 'info', 'General business', 'Note taking, wikis and knowledge tools. Examples: Notion, Evernote Web Clipper, OneNote, Obsidian.'),
  ('Design and creative', 'general-business/design-and-creative', 'general-business', 'info', 'General business', 'Graphics, video editing and design tools. Examples: Adobe Creative Cloud, Figma, Canva, DaVinci Resolve.'),
  ('Screen capture and recording', 'general-business/screen-capture-and-recording', 'general-business', 'review', 'General business', 'Tools that record or capture the screen. Examples: Awesome Screen Recorder & Screenshot, OBS Studio, ShareX, Loom, Snagit.'),
  ('Business applications', 'general-business/business-applications', 'general-business', 'info', 'General business', 'ERP, CRM, accounting and other line-of-business clients. Examples: SAP GUI, TOTVS, Salesforce, Power BI Desktop.'),
  ('Compression and file utilities', 'general-business/compression-and-file-utilities', 'general-business', 'info', 'General business', 'Archive and file management utilities. Examples: 7-Zip, WinRAR, Everything.'),
  ('Web browsers', 'general-internet/web-browsers', 'general-internet', 'info', 'General internet', 'Web browsers and their release channels. Examples: Google Chrome, Microsoft Edge, Firefox, Brave, Opera.'),
  ('Browser utilities', 'general-internet/browser-utilities', 'general-internet', 'info', 'General internet', 'New tab pages, translators, ad blockers and other extensions that change pages. Examples: Momentum, uBlock Origin, Google Translate, Dark Reader.'),
  ('Learning', 'general-internet/learning', 'general-internet', 'info', 'General internet', 'Education and language learning apps. Examples: Duolingo on the Web, Coursera, Khan Academy.'),
  ('Legacy Chrome apps', 'general-internet/legacy-chrome-apps', 'general-internet', 'review', 'General internet', 'Deprecated Chrome apps kept from old browser profiles. Examples: Docs, Sheets, Slides, Gmail, YouTube, Google Drive (legacy apps).'),
  ('Updaters', 'software-update/updaters', 'software-update', 'info', 'Software update', 'Background services that update other software. Examples: Google Update, Microsoft Edge Update, Adobe Updater, Java Update Scheduler.'),
  ('Virtualization and containers', 'infrastructure/virtualization-and-containers', 'infrastructure', 'review', 'Infrastructure', 'Hypervisors, containers and Linux subsystems that run isolated environments. Examples: VirtualBox, VMware Workstation, Docker Desktop, WSL.'),
  ('Admin tools', 'infrastructure/admin-tools', 'infrastructure', 'info', 'Infrastructure', 'Tools used to administer systems and inspect networks. Examples: Wireshark, RSAT, Sysinternals, mRemoteNG.'),
  ('Web and app servers', 'network-services/web-and-app-servers', 'network-services', 'review', 'Network services', 'Web servers and application runtimes that accept connections. Examples: IIS, Apache httpd, nginx, Tomcat, php-fpm.'),
  ('Mail servers', 'network-services/mail-servers', 'network-services', 'review', 'Network services', 'Software that sends or receives mail for other users or systems. Examples: Exchange Server, hMailServer, Postfix, Exim, Dovecot.'),
  ('Database servers', 'network-services/database-servers', 'network-services', 'review', 'Network services', 'Database engines running on the computer. Examples: SQL Server, MySQL, PostgreSQL, MongoDB, Redis.'),
  ('Local development stacks', 'network-services/local-development-stacks', 'network-services', 'review', 'Network services', 'Bundled web stacks for local development. Examples: XAMPP, WampServer, Laragon, MAMP.'),
  ('ICS engineering and HMI software', 'industrial-control-system/ics-engineering-and-hmi-software', 'industrial-control-system', 'review', 'Industrial control system', 'Software that programs or monitors PLCs and industrial equipment. Examples: Siemens TIA Portal, Rockwell Studio 5000, Schneider EcoStruxure.'),
  ('Phone companions', 'mobile-applications/phone-companions', 'mobile-applications', 'info', 'Mobile applications', 'Apps that connect phones to the computer. Examples: Phone Link, iTunes, Android File Transfer, Samsung Smart Switch.'),
  ('OS components and runtimes', 'system-applications/os-components-and-runtimes', 'system-applications', 'info', 'System applications', 'Operating system features, redistributables and runtimes installed as dependencies. Examples: Microsoft Visual C++ Redistributable, .NET Runtime, Java Runtime, WebView2.'),
  ('Drivers and hardware utilities', 'system-applications/drivers-and-hardware-utilities', 'system-applications', 'info', 'System applications', 'Drivers and vendor utilities for devices. Examples: Realtek Audio, Intel Graphics, Logi Options+, NVIDIA App.'),
  ('OEM utilities', 'system-applications/oem-utilities', 'system-applications', 'info', 'System applications', 'Manufacturer tools preinstalled on the computer. Examples: Dell Command Update, HP Support Assistant, Lenovo Vantage.'),
  ('Browser components', 'system-applications/browser-components', 'system-applications', 'info', 'System applications', 'Components that ship with the browser or its store. Examples: Chrome Web Store Payments, Chrome Media Router, Edge relevant text changes.'),
  ('Sophos agents and tools', 'sophos-applications/sophos-agents-and-tools', 'sophos-applications', 'info', 'Sophos applications', 'Sophos endpoint, ZTNA, VPN and management software. Examples: Sophos Endpoint Agent, Sophos Connect, Sophos ZTNA client.'),
  ('Antivirus and EDR (third party)', 'security-and-identity/antivirus-and-edr-third-party', 'security-and-identity', 'review', null, 'Security agents from other vendors; they may conflict with the Sophos agent. Examples: Malwarebytes, ESET, Kaspersky, CrowdStrike Falcon.'),
  ('Password managers', 'security-and-identity/password-managers', 'security-and-identity', 'info', null, 'Vaults that store credentials, as apps or browser extensions. Examples: Keeper, Bitwarden, 1Password, LastPass.'),
  ('Authenticators and MFA', 'security-and-identity/authenticators-and-mfa', 'security-and-identity', 'info', null, 'One-time password and passkey tools. Examples: Microsoft Authenticator, Authy, YubiKey Manager.'),
  ('Encryption tools', 'security-and-identity/encryption-tools', 'security-and-identity', 'review', null, 'Disk, file or container encryption outside managed policy. Examples: VeraCrypt, AxCrypt, Cryptomator.'),
  ('Security testing tools', 'security-and-identity/security-testing-tools', 'security-and-identity', 'review', null, 'Scanners, sniffers and offensive tools; legitimate for security teams and common in attacks. Examples: Nmap, Advanced IP Scanner, Burp Suite, Metasploit.'),
  ('IDEs and editors', 'developer-tools/ides-and-editors', 'developer-tools', 'info', null, 'Code editors and integrated development environments. Examples: Visual Studio Code, Visual Studio, IntelliJ IDEA, Notepad++.'),
  ('Language runtimes and SDKs', 'developer-tools/language-runtimes-and-sdks', 'developer-tools', 'info', null, 'Compilers, interpreters and SDKs. Examples: Node.js, Python, JDK, PHP, Go.'),
  ('CLIs and version control', 'developer-tools/clis-and-version-control', 'developer-tools', 'info', null, 'Command-line tools, source control and cloud CLIs. Examples: Git, GitHub CLI, AWS CLI, Azure CLI.'),
  ('Libraries and packages', 'developer-tools/libraries-and-packages', 'developer-tools', 'info', null, 'Packages installed by npm, pip, Homebrew or Chocolatey that are libraries rather than apps. Examples: typescript, requests, lodash.'),
  ('IDE extensions', 'developer-tools/ide-extensions', 'developer-tools', 'info', null, 'Extensions for code editors that are not AI assistants. Examples: ESLint, Prettier, Python for VS Code.'),
  ('Adware and browser hijackers', 'unwanted-software/adware-and-browser-hijackers', 'unwanted-software', 'not_allowed', null, 'Software that injects ads, changes the search engine or tracks browsing without clear consent. Examples: Search hijacker extensions, bundled toolbars.'),
  ('Cracks and license bypass', 'unwanted-software/cracks-and-license-bypass', 'unwanted-software', 'not_allowed', null, 'Keygens, activators and patched installers. Examples: KMS activators, keygens.'),
  ('Crypto miners', 'unwanted-software/crypto-miners', 'unwanted-software', 'not_allowed', null, 'Software that mines cryptocurrency on the computer. Examples: XMRig, NiceHash Miner.'),
  ('Other', 'other/other', 'other', 'info', null, 'Software that fits no other category; use only when nothing else applies.')
) as v (name, slug, parent_slug, attention, firewall, description)
join public.categories p on p.slug = v.parent_slug;

